    protected internal override void dm_init_vars()
    {
        base.dm_init_vars();
        icon = Dm.list(Dm.kv("icon", Dm.resource("icons/obj/weapons/khopesh.dmi")), Dm.kv("state", "ash_blade"), Dm.kv("frame", 1), Dm.kv("dir", 2), Dm.kv("moving", 0)); // tg: code/modules/antagonists/heretic/knowledge/ash_lore.dm:6
        description = Dm.list("The Path of Ash revolves around fire, mobility and brutal crowd control against single opponents.", "Play this path if you are new to Heretic, or really enjoy hit and run playstyles."); // tg: code/modules/antagonists/heretic/knowledge/ash_lore.dm:13
        pros = Dm.list("Very potent even from the beginning of the path.", "Easy access to a mobility spells and expanded vision.", "Very powerful mark effect."); // tg: code/modules/antagonists/heretic/knowledge/ash_lore.dm:17
        cons = Dm.list("Has less power than most heretics beyond their starting abilities.", "Lacks durability in long conflicts.", "Reliant on hitting fast and hard before their opponents can mount proper countermeasures."); // tg: code/modules/antagonists/heretic/knowledge/ash_lore.dm:22
        tips = Dm.list("Your Mansus Grasp applies a short blind and a mark that puts your opponent into stamina crit when triggered by your blade. The mark can spread to nearby opponents.", "Selecting this path makes you immune to high temperature damage. Remember, however, that your clothes can still burn! If you want to protect yourself from your own fire, wear a Scorched Mantle.", "Your Scorched Mantle will keep you on fire while protecting you from the ill effects of it. Use this to your advantage by running into groups of enemies, spreading fire far and wide.", "Do not neglect the Mask of Madness. It will slowly sap the stamina of your enemies and make them hallucinate.", "Make sure to set as many enemies on fire as you possibly can! Nightwatcher's Rebirth will heal you and have its cooldown reduced based on how many mobs you siphon.", "Your ascension grants you complete immunity to environmental hazards, including bombs! But you are still vulnerable to more conventional weaponry. Do not become overconfident."); // tg: code/modules/antagonists/heretic/knowledge/ash_lore.dm:27
    }
}

